probe.script:
(async () => {
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));

  /* Кадры считаются по rAF: он тикает ровно тогда, когда браузер рисует.
     Смотрим не среднее, а РАСПРЕДЕЛЕНИЕ интервалов: средние 60 кадров при
     одном провале в 120 мс — это заметный рывок, которого среднее не покажет. */
  function record(durationMs) {
    return new Promise((resolve) => {
      const marks = [];
      const t0 = performance.now();
      const tick = (now) => {
        marks.push(now);
        if (now - t0 < durationMs) requestAnimationFrame(tick);
        else {
          const gaps = [];
          for (let i = 1; i < marks.length; i += 1) gaps.push(marks[i] - marks[i - 1]);
          gaps.sort((a, b) => a - b);
          const at = (p) => gaps.length ? Number(gaps[Math.min(gaps.length - 1, Math.floor(gaps.length * p))].toFixed(1)) : 0;
          resolve({
            frames: marks.length,
            seconds: Number(((marks[marks.length - 1] - marks[0]) / 1000).toFixed(2)),
            fps: Number((((marks.length - 1) * 1000) / (marks[marks.length - 1] - marks[0])).toFixed(1)),
            medianGapMs: at(0.5),
            p95GapMs: at(0.95),
            worstGapMs: gaps.length ? Number(gaps[gaps.length - 1].toFixed(1)) : 0,
            over32ms: gaps.filter((g) => g > 32).length
          });
        }
      };
      requestAnimationFrame(tick);
    });
  }

  const rail = document.querySelector('.psr__grid');
  if (!rail) return { error: 'ряд разделов не найден' };

  /* 1. Простой: сколько кадров даёт окно, когда ничего не происходит.
        Это опорное число — с ним сравниваются остальные. */
  const idle = await record(1500);

  /* Шести разделов мало, чтобы ряд переполнился: на 1024 точках они
     помещаются целиком, и мерить было бы нечего. Удваиваем кнопки клонами —
     это ровно тот случай, ради которого листание и сделано («разделов будет
     много»). Клоны — копии настоящих кнопок, то есть та же вёрстка и та же
     работа при отрисовке. */
  const originals = [...rail.querySelectorAll('.psr__btn')];
  for (let pass = 0; pass < 2; pass += 1) {
    for (const node of originals) rail.appendChild(node.cloneNode(true));
  }
  await wait(120);

  /* 2. Листание ряда так, как это делает палец: браузер сам меняет scrollLeft
        (touch-action: pan-x). Гоняем его туда-обратно. */
  const max = rail.scrollWidth - rail.clientWidth;
  let running = true;
  const t0 = performance.now();
  const drive = () => {
    if (!running) return;
    const phase = ((performance.now() - t0) % 2000) / 2000;
    rail.scrollLeft = max * (phase < 0.5 ? phase * 2 : 2 - phase * 2);
    requestAnimationFrame(drive);
  };
  requestAnimationFrame(drive);
  const railScroll = await record(2500);
  running = false;
  rail.scrollLeft = 0;

  /* 3. То же мышью — через наш собственный перенос (pointerType: mouse).
        Пальцем листает браузер, мышью мы, и это разные пути кода. */
  const box = rail.getBoundingClientRect();
  const ev = (type, x) => rail.dispatchEvent(new PointerEvent(type, { bubbles: true, clientX: x, clientY: box.top + box.height / 2, pointerId: 2, pointerType: 'mouse', isPrimary: true, buttons: type === 'pointerup' ? 0 : 1 }));
  Element.prototype.setPointerCapture = function () {};
  Element.prototype.releasePointerCapture = function () {};
  Element.prototype.hasPointerCapture = function () { return false };
  let x = box.right - 40;
  ev('pointerdown', x);
  let dragging = true;
  const dragLoop = async () => {
    while (dragging) {
      x -= 9;
      if (x < box.left + 40) x = box.right - 40;
      ev('pointermove', x);
      await wait(16);
    }
  };
  const drag = dragLoop();
  const mouseDrag = await record(2000);
  dragging = false;
  await drag;
  ev('pointerup', x);

  /* 4. Прокрутка длинной таблицы — журнал чеков под рядом. */
  const table = document.querySelector('.pj__scroll') || document.querySelector('.dsk__scroll');
  let tableScroll = null;
  if (table) {
    let go = true;
    const s0 = performance.now();
    const scrollDrive = () => {
      if (!go) return;
      const phase = ((performance.now() - s0) % 2400) / 2400;
      const limit = table.scrollHeight - table.clientHeight;
      table.scrollTop = limit * (phase < 0.5 ? phase * 2 : 2 - phase * 2);
      requestAnimationFrame(scrollDrive);
    };
    requestAnimationFrame(scrollDrive);
    tableScroll = await record(2500);
    go = false;
  }

  return {
    buttonsWhileMeasuring: rail.querySelectorAll('.psr__btn').length,
    scrollWidth: rail.scrollWidth,
    clientWidth: rail.clientWidth,
    overflowPx: rail.scrollWidth - rail.clientWidth,
    idle,
    railScroll,
    mouseDrag,
    tableScroll
  };
})()
